arguments.command:
cd /tmp/joey-wt && for b in rachel monica phoebe chandler joey ross; do
  echo "=== friend/$b ===";
  git log origin/friend/$b --format=%H --grep="Friend-Message: 1" | while read sha; do
    msg=$(git show --no-patch --format=%B $sha);
    ep=$(echo "$msg" | grep '^Episode:' | head -1);
    if echo "$ep" | grep -q "S05/E17"; then echo "$sha"; fi;
  done;
done | wc -l
